#!/usr/bin/env python3"""Add --update-base CLI flag to prompts.py."""from pathlib import Pathtarget = Path("bin/agent/prompts.py")raw = target.read_bytes()old = b'    if "--reset-system" in args:\r\n        print(reset_system_prompts_to_defaults())\r\n        return 0'new = b'    if "--update-base" in args:\r\n        print(update_base_prompts_from_xml())\r\n        return 0\r\n    if "--reset-system" in args:\r\n        print(reset_system_prompts_to_defaults())\r\n        return 0'if b'"--update-base"' not in raw:    if old in raw:        raw = raw.replace(old, new, 1)        target.write_bytes(raw)        print("OK: --update-base CLI flag added")    else:        print("ERROR: CLI anchor not found")else:    print("SKIP: --update-base already exists")